begin;create table public.rental_maintenance_assignments(id uuid primary key default gen_random_uuid(),request_id uuid not null unique references public.rental_maintenance_requests(id),organisation_id uuid not null references public.organisations(id),assignee_name text not null,assignee_contact text,assigned_by uuid not null references auth.users(id),assigned_at timestamptz not null default now(),sla_due_at timestamptz not null,triage_notes text,priority_at_assignment text not null check(priority_at_assignment in('emergency','urgent','routine')),status text not null default 'assigned' check(status in('assigned','accepted','in_progress','completed','cancelled')));create index rental_maintenance_assignments_sla_idx on public.rental_maintenance_assignments(organisation_id,status,sla_due_at);alter table public.rental_maintenance_assignments enable row level security;revoke all on public.rental_maintenance_assignments from anon,authenticated;grant select on public.rental_maintenance_assignments to authenticated;create policy rental_maintenance_assignments_read on public.rental_maintenance_assignments for select to authenticated using(exists(select 1 from public.rental_maintenance_requests r join public.rental_properties p on p.id=r.property_id where r.id=request_id and public.rental_branch_access(p.organisation_id,p.branch_id)));create or replace function public.rental_triage_maintenance_request(x uuid,pr text,n text,an text,ac text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_maintenance_requests%rowtype;aid uuid;d timestamptz;begin if auth.uid() is null or pr not in('emergency','urgent','routine') or length(btrim(coalesce(an,'')))=0 then raise exception 'Priority and assignee are required';end if;select * into r from public.rental_maintenance_requests where id=x for update;if not found or not exists(select 1 from public.rental_properties p where p.id=r.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;if r.status in('resolved','cancelled') then raise exception 'Closed requests cannot be assigned';end if;d:=now()+case pr when 'emergency' then interval '4 hours' when 'urgent' then interval '24 hours' else interval '72 hours' end;update public.rental_maintenance_requests set priority=pr,status='assigned' where id=r.id;insert into public.rental_maintenance_assignments(request_id,organisation_id,assignee_name,assignee_contact,assigned_by,sla_due_at,triage_notes,priority_at_assignment)values(r.id,r.organisation_id,btrim(an),nullif(btrim(coalesce(ac,'')),''),auth.uid(),d,nullif(btrim(coalesce(n,'')),''),pr)on conflict(request_id)do update set assignee_name=excluded.assignee_name,assignee_contact=excluded.assignee_contact,assigned_by=excluded.assigned_by,assigned_at=now(),sla_due_at=excluded.sla_due_at,triage_notes=excluded.triage_notes,priority_at_assignment=excluded.priority_at_assignment,status='assigned' returning id into aid;return jsonb_build_object('request_id',r.id,'assignment_id',aid,'sla_due_at',d,'status','assigned');end$$;revoke execute on function public.rental_triage_maintenance_request(uuid,text,text,text,text) from public,anon;grant execute on function public.rental_triage_maintenance_request(uuid,text,text,text,text) to authenticated;commit;;
